  async function _postBchTipNote(pk, amt, addr, txid){
    try{
      const who='nostr:'+NT().nip19.npubEncode(pk);
      let body=`🟢 Tipped${amt?(' '+amt+' BCH'):''} ${who} via Bitcoin Cash 💚`;
      if(txid) body+=`\n\nTx: https://blockchair.com/bitcoin-cash/transaction/${txid}`;
      body+=`\n\n— sent with PosterChan; add your BCH address at https://poster.place to receive Bitcoin Cash tips too`;
      const tags=[['p',pk],['t','bchtip']].concat(amt?[['amount_bch',String(amt)]]:[]).concat(txid?[['bch_tx',txid]]:[]);
      const r=await publish(1, body, tags); if(r && r.ok) toast('🟢 tip note posted');   // failure toast by publish()
    }catch(e){ toast('could not post tip note'); }
  }
  // A kind-1 address-tip note (BCH `t:bchtip` / Monero `t:monerotip`) → the pieces for a proper
  // "🟢 tipped you 0.01 BCH" notification instead of a generic "mentioned you". Shared by the live
  // toast/OS-notification builder AND the Notifications list renderer so both agree.
  function _tipNote(ev){
    if(!ev || ev.kind!==1 || !ev.tags) return null;
    const has=v=>ev.tags.some(t=>t[0]==='t'&&t[1]===v);
    const amtOf=k=>(ev.tags.find(t=>t[0]===k)||[])[1]||'';
    if(has('bchtip'))    return { icon:'🟢', amt:amtOf('amount_bch'), unit:'BCH' };
    if(has('monerotip')) return { icon:'ɱ', amt:amtOf('amount_xmr'), unit:'XMR' };
    return null;
  }
  function bech32ToBytes(s){ const d=NT().nip19; throw new Error('lnurl decode unsupported'); }
  async function doBlock(pk){
    if(!IS_ADMIN) return;
    if(!await uiConfirm('Block this npub on the relay? Their events get rejected and purged.')) return;
    try {
      const auth = await sign(27235, 'block', [['action','block'],['p',pk]]);
      const r = await fetch('/client/block', { method:'POST', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({ target: pk, auth: btoa(JSON.stringify(auth)) }) }).then(r=>r.json());
      toast(r.ok ? 'blocked on relay' : ('block failed: ' + (r.error||'')));
    } catch(e){ toast('block failed'); }
  }
  function eTags(id,pk){ const t=[['e',id]]; if(pk)t.push(['p',pk]); return t; }
  // The emoji picker is the only way to react now (the dedicated 🤍 like button was removed). After
  // publishing, refresh the counters in place (decorateCounts) so the reaction count goes up and the
  // react button shows your chosen emoji — without re-rendering/resetting the whole feed.
  const REACTION_EMOJIS=['❤️','🔥','😂','🤣','😮','😯','😢','😭','👍','👎','🤙','💀','⚡','🚀','🤔','🥰','😍','😘','😎','🤩','🥳','😏','😊','🙂','😉','😌','😋','😛','😜','🤪','😅','😆','😁','😄','😀','🙃','😇','🤗','🤭','🤫','🫡','🧐','🤓','🥸','😐','😑','😶','🙄','😬','🤨','😴','🤤','😪','😷','🤒','🤕','🤢','🤮','🥵','🥶','🥴','😵','🤯','😳','🥺','😤','😠','😡','🤬','😱','😨','😰','😥','😓','🥱','🤠','😈','👿','👹','👺','🤡','💩','👻','👽','👾','🤖','🎃','👀','👏','🙌','🙏','🤝','💪','👊','✌️','🤞','🤟','🤘','👌','🫶','💯','💔','🧡','💛','💚','💙','💜','🖤','🤍','⭐','✨','💥','🎉'];
  // Shared emoji popover anchored under a button. onPick(emoji, close) decides what to do (react,
  // or insert into a textarea — for the latter it can keep the picker open for multiple inserts).
  // Place a popover. On phones it becomes a full-width bottom action-sheet with a dim backdrop
  // (always attached + readable — a wide menu can't sensibly hang off a tiny right-edge button on a
  // narrow screen). On desktop it's an anchored dropdown: below the button if it fits, else flipped
  // above; left-aligned, or right-aligned when the button sits near the right edge.
  // Match a popover to the app's desktop scale. These menus hang off <html>, not <body> — _placePop's
  // fixed-position math needs a parent the zoom doesn't touch — which also means the desktop
  // body{zoom:.67-.77} tiers never reached them: the ☰ menu measured 1.22x-1.40x the post it drops out
  // of on every laptop-width desktop. The CSS sizes itself off --pop-scale (see .menu-pop).
  // MUST be called BEFORE the popover is inserted: set afterwards, Chrome restyles the popover itself
  // but leaves its buttons at the unscaled size (measured, in the app and in isolation). Skipped
  // below 1180px, where the menu is a full-width bottom sheet and the app isn't zoomed anyway.
  function _scalePop(pop){
    if(window.matchMedia('(max-width:1179px)').matches) return pop;
    const z=parseFloat(getComputedStyle(document.body).zoom);
    if(z && z!==1) pop.style.setProperty('--pop-scale', String(z));
    return pop;
  }
  function _placePop(pop, anchorBtn){
    // ONE consistent rule for every menu (timeline ☰, profile ☰, compose Attach/React/Translate,
    // emoji): without the desktop right column (<1180px) a right-edge button's menu would spill
    // ~1-2" to the left, so ALL menus become a centered bottom action-sheet there. At >=1180px the
    // layout has room, so they're anchored dropdowns under their button.
    if(window.matchMedia('(max-width:1179px)').matches){
      document.querySelectorAll('.pop-backdrop').forEach(b=>b.remove());
      const bd=document.createElement('div'); bd.className='pop-backdrop';
      document.documentElement.appendChild(bd);
      pop.classList.add('sheet');   // CSS pins it to the bottom as a centered card
      return;
    }
    const M=8, vw=window.innerWidth, vh=window.innerHeight;
    const r=(anchorBtn||document.body).getBoundingClientRect();
    const pw=pop.offsetWidth, ph=pop.offsetHeight;   // ph already respects the popover's CSS max-height
    // Horizontal: drop straight under the button (left edges aligned, like a normal dropdown). If
    // that would run off the right edge (a button near the right side), right-align it to the button
    // instead so it stays attached. Always clamp on-screen.
    let left = r.left;
    if(left + pw > vw - M) left = r.right - pw;
    left = Math.max(M, Math.min(left, vw-M-pw));
    // Vertical: just below the button; if it would overflow the bottom, flip above (bottom hugs the
    // button) when there's room, otherwise pin within the viewport. Keeps it attached to the button.
    let top = r.bottom + 6;
    if(top + ph > vh - M){
      const above = r.top - 6 - ph;
      top = (above >= M) ? above : Math.max(M, vh - M - ph);
    }
    pop.style.left=left+'px'; pop.style.top=top+'px';
    // BULLETPROOF on-screen guarantee: re-measure the menu's REAL rendered rect (the earlier offsetWidth
    // can be wrong/stale for long items, so a right-edge ☰ menu hung off the right and taps fell through
    // to the Zap button behind it) and shove it fully inside the viewport. getBoundingClientRect forces a
    // synchronous layout, so this corrects before the first paint — no visible jump.
    {
      const b=pop.getBoundingClientRect();
      if(b.right > vw - M) left -= (b.right - (vw - M));
      if(left < M) left = M;
      if(b.bottom > vh - M) top -= (b.bottom - (vh - M));
      if(top < M) top = M;
      pop.style.left=left+'px'; pop.style.top=top+'px';
    }
  }
  // Keyboard navigation for the flat button popovers (the reaction grid, the ☰ menu). They were
  // mouse-only, so a reaction could not be chosen from the keyboard at all. Bound in the CAPTURE phase and
  // stopping what it handles, so the global scroll/post-action keys cannot also fire while one is open.
  function _popKeys(pop, sel, activate, close, opts){
    opts=opts||{};
    const items=()=>[...pop.querySelectorAll(sel)];
    let i=-1;
    const mark=()=>{ const els=items(); els.forEach((b,n)=>b.classList.toggle('kb', n===i));
      if(els[i]) els[i].scrollIntoView({block:'nearest'}); };
    // The emoji grid wraps, so Up/Down must move a ROW, not one button. Buttons on the same row share an
    // offsetTop — count them to get the row length, which adapts to whatever width the popover ended up.
    const rowLen=()=>{ const els=items(); if(els.length<2) return 1;
      const top=els[0].offsetTop; let n=0;
      for(const el of els){ if(el.offsetTop!==top) break; n++; }
      return Math.max(1,n); };
    const onKey=e=>{
      if(e.altKey||e.ctrlKey||e.metaKey) return;
      if(!pop.isConnected){ detach(); return; }   // closed by a click/✕ → stop listening, don't leak
      // A sheet with a search box (the Effects studio) still needs the caret keys while you type, so it
      // opts into a SUBSET. A bare popover has no text field and takes everything.
      const t=e.target;
      // SELECT is in here for the Blossom picker's folder dropdown: the arrows CHANGE a select's value, so
      // taking them for the grid cursor made the dropdown unusable from the keyboard.
      if(t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName||''))
         && !(opts.inText||[]).includes(e.key)) return;
      const els=items(); if(!els.length) return;
      const k=e.key; let d=0;
      if(k==='Escape'){ e.preventDefault(); e.stopPropagation(); close(); return; }
      if(k==='Enter'||k===' '){ if(i>=0){ e.preventDefault(); e.stopPropagation(); activate(els[i]); } return; }
      // hjkl move here too when Vim keys are on — the popover is a grid like any other, and having to
      // switch back to the arrows just to pick a reaction is exactly the break in flow vim mode avoids.
      // (g/G are single-press here: there is no other g binding inside a popover to disambiguate from.)
      const vim=_vimOn();
      if(k==='ArrowRight'||(vim&&k==='l')) d=1;
      else if(k==='ArrowLeft'||(vim&&k==='h')) d=-1;
      else if(k==='ArrowDown'||(vim&&k==='j')) d=rowLen();
      else if(k==='ArrowUp'||(vim&&k==='k')) d=-rowLen();
      else if(k==='Home'||(vim&&k==='g')){ e.preventDefault(); e.stopPropagation(); i=0; mark(); return; }
      else if(k==='End'||(vim&&k==='G')){ e.preventDefault(); e.stopPropagation(); i=els.length-1; mark(); return; }
      else return;
      e.preventDefault(); e.stopPropagation();
      i = i<0 ? (d>0?0:els.length-1) : Math.max(0, Math.min(els.length-1, i+d));
      mark();
    };
    const detach=()=>document.removeEventListener('keydown', onKey, true);
    document.addEventListener('keydown', onKey, true);
    return detach;
  }
  // Recently-used picks (unicode chars and :shortcodes: alike) — the top row of the picker, because
