  function gifPicker(ta){
    const bg=document.createElement('div'); bg.className='modal-bg'; bg.style.zIndex='200';
    bg.innerHTML=`<div class="modal glass neon-border"><h3><svg class="ic h-ic" aria-hidden="true"><use href="#i-film"></use></svg>GIFs</h3><input class="input" id="gif-q" placeholder="search GIFs…" autocomplete="off"><div id="gif-grid" class="gif-grid"><div class="spinner"></div></div></div>`;
    bg.onclick=e=>{ if(e.target===bg) bg.remove(); };
    $('#modal-root').appendChild(bg);
    const grid=bg.querySelector('#gif-grid'), q=bg.querySelector('#gif-q'); let t=null;
    async function load(query){
      grid.innerHTML='<div class="spinner"></div>';
      let j={}; try{ j=await fetch('/client/gif?q='+encodeURIComponent(query||'')).then(r=>r.json()); }catch(_){}
      const rs=j.results||[];
      if(!rs.length){ grid.innerHTML='<div class="empty">'+(j.error?'GIF search not configured (set a Tenor key in Admin).':'No GIFs.')+'</div>'; return; }
      grid.innerHTML=rs.map(g=>`<img class="gif-item" src="${enc(g.preview)}" data-url="${enc(g.url)}" loading="lazy">`).join('');
      grid.querySelectorAll('.gif-item').forEach(im=> im.onclick=()=>{ ta.value+=(ta.value?'\n':'')+im.dataset.url+' '; ta.dispatchEvent(new Event('input',{bubbles:true})); bg.remove(); toast('GIF added'); });
    }
    q.oninput=()=>{ clearTimeout(t); t=setTimeout(()=>load(q.value.trim()),350); };
    load(''); q.focus();
  }
  // `ta` mode (default): tapping a file appends its media URL to the textarea (post/DM composer).
  // `onPick` mode: instead of pasting a link, call onPick({url,type,ext}) with the chosen blob — used
  // by AI chat, which fetches the bytes into a real attachment rather than a URL in the message text.
  // `opts.filter(blob)` narrows what's offered (Meme Builder: images/videos only) and `opts.title`
  // renames the header. Callers that only want a SUBSET must come through here rather than rolling
  // their own grid — the folder bar, the encrypted-blob hygiene and the thumbnails all live here, and
  // a private copy silently ships a flat, folderless drive (which is exactly what the meme picker did).
  function blossomPicker(ta, onPick, opts={}){
    const server=mediaServer(); if(!server){ toast('no media server set'); return; }
    const bg=document.createElement('div'); bg.className='modal-bg'; bg.style.zIndex='200';
    bg.innerHTML=`<div class="modal glass neon-border bp-modal">
      <div class="bp-head"><h3>${enc(opts.title||'🌸 Blossom Files')}</h3>
        <div id="bp-folders" class="bp-folders"></div></div>
      <div id="bp-grid" class="files-grid"><div class="spinner"></div></div></div>`;
    // This sheet is hand-rolled rather than built by modal()/subModal(), so it used to get NONE of what
    // they provide: no Escape, no focus trap, and body.modal-open was never set (so `/` and the other
    // global keys still fired at the view behind it). One close path now does all of it.
    const close=()=>{ bg.remove(); const root=$('#modal-root');
      if(!root || !root.children.length) document.body.classList.remove('modal-open'); };
    bg.onclick=e=>{ if(e.target===bg) close(); };
    $('#modal-root').appendChild(bg);
    document.body.classList.add('modal-open');
    _trapFocus(bg.querySelector('.modal'), close);
    // The grid is a grid of DIVs — nothing focusable, so Tab could never reach a file and Enter had
    // nothing to press. _popKeys is the app's grid cursor (arrows, and hjkl when Vim keys are on, with
    // the row length measured from the layout), the same one the effects and emoji pickers use.
    _popKeys(bg, '#bp-grid .file-card', el=>el.click(), close);
    FilesIdx.loadLocal();
    (async()=>{
      // Folder names live in the encrypted Files index, which is only fetched when you OPEN Files —
      // so without this pull the picker showed a flat drive to anyone who hadn't been there yet.
      if(!FilesIdx._pulled){ FilesIdx._pulled=true; try{ await FilesIdx.pull(); }catch(_){ } }
      let list=[]; try{ const r=await fetch(server+'/list/'+ME.pubkey); if(r.ok) list=await r.json(); }catch(_){}
      // Same filter as the Files grid: hide the octet-stream noise (encrypted ciphertext, stale/live
      // index blobs, unnamed binaries) — none of it renders as media in a post, and it floods the picker.
      list = list.filter(b=>{
        if(b.sha256===FilesIdx._lastIndexSha) return false;        // the encrypted Files index blob itself
        const m=FilesIdx.meta(b.sha256);
        if(m && m.enc) return false;                               // encrypted ciphertext — not publicly viewable
        if(!m && /octet-stream/.test(b.type||'')) return false;    // stale index blobs / unnamed binaries
        if(FilesIdx.isEncFolder(FilesIdx.folderOf(b.sha256))) return false;   // ditto for a whole encrypted folder
        if(opts.filter && !opts.filter(b)) return false;            // caller's own narrowing (e.g. media only)
        return true;
      });
      const grid=bg.querySelector('#bp-grid'), fbar=bg.querySelector('#bp-folders');
      // Only folders that actually hold something visible here, so you can't tap into an empty one.
      const used=new Set(list.map(b=>FilesIdx.folderOf(b.sha256)||''));
      const folders=[['','🗂 All']].concat(
        FilesIdx.folders().filter(f=>!FilesIdx.isEncFolder(f) && used.has(f)).map(f=>[f,'📁 '+f]));
      let cur='';
      const draw=()=>{
        const shown=list.filter(b=> cur==='' || (FilesIdx.folderOf(b.sha256)||'')===cur);
        grid.innerHTML = shown.length ? shown.map(b=>
          `<div class="file-card" data-url="${enc(b.url)}" data-type="${enc(b.type||'')}">${blobThumb(b)}</div>`).join('')
          : `<div class="empty">${cur?'Nothing in this folder.':enc(opts.empty||'No files yet — upload some in the Files tab.')}</div>`;
        grid.querySelectorAll('[data-url]').forEach(el=> el.onclick=()=>{
          const type=el.dataset.type||''; const ext=_MIME_EXT[type]||''; const url=el.dataset.url;
          close();
          if(onPick){ try{ onPick({url, type, ext}); }catch(_){} return; }
          // ...only when the URL doesn't already carry one — the server's listing now includes the
          // extension, and appending unconditionally produced "…/<sha>.png.png" (which still served,
          // but is what every other client shows in the note).
          const _need = ext && !/\.[a-z0-9]{1,8}$/i.test(url.split('?')[0]);
          ta.value+=(ta.value?'\n':'')+url+(_need?('.'+ext):'');
          ta.dispatchEvent(new Event('input',{bubbles:true})); toast('attached'); });

      };
      // ONE ROW, always. A wrapping chip bar grew with the folder count until it filled a phone
      // screen, and its translucent background let the grid scroll visibly through it. A select is
      // a fixed-height control and opens the OS picker on mobile.
      fbar.innerHTML = folders.length>1
        ? `<label class="bp-folderlbl">📁<select class="input bp-folder-sel" id="bp-folder-sel">${
            folders.map(([v,l])=>`<option value="${enc(v)}">${enc(l)}</option>`).join('')}</select></label>`
        : '';
      { const sel=fbar.querySelector('#bp-folder-sel');
        if(sel) sel.onchange=()=>{ cur=sel.value||''; draw(); }; }
      draw();
    })();
  }

  // ---- 4chan browser (Discover) — live catalog/thread via the /api/4chan/* backend (proxies
  // a.4cdn.org through the built-in proxy). Content is ephemeral + re-fetchable, so it is NOT stored
  // as relay events (that would bloat the WoT relay with non-Nostr junk); the view fetches fresh.
  // ---------- Pics: a picture-first feed (NIP-68 kind-20 + image notes) as a media grid ----------
  function _firstImage(ev){
    for(const t of (ev.tags||[])){
      if((t[0]==='url'||t[0]==='image') && /^https?:\/\//i.test(t[1]||'')) return t[1];
      if(t[0]==='imeta'){ const u=(t.find(x=>/^url\s/i.test(x))||'').replace(/^url\s+/i,''); if(/^https?:\/\//i.test(u)) return u; }
    }
    const m=(ev.content||'').match(/https?:\/\/[^\s)<]+\.(?:jpe?g|png|gif|webp|avif)(?:\?[^\s)<]*)?/i);
    return m?m[0]:null;
  }
  async function renderPics(){
    const feed=$('#feed');
    feed.innerHTML='<div class="pics-grid" id="pics-grid"><div class="spinner"></div></div>';
    let evs=[];
    try{ evs=await Relay.query([{kinds:[20], limit:80},{kinds:[1], limit:160}]); }catch(_){}
    evs.forEach(e=>{ Store.saveEvent(e); needProfile(e.pubkey); });
    if(VIEW!=='pics') return;
    const pics=[]; const seen=new Set();
    for(const e of evs.sort((a,b)=>b.created_at-a.created_at)){
      if(e.kind===1 && isReply(e)) continue;
      if(isMutedView(e)) continue;
      const img=_firstImage(e); if(!img || seen.has(e.id)) continue;
      seen.add(e.id); pics.push({e,img});
      if(pics.length>=120) break;
    }
    const grid=$('#pics-grid'); if(!grid) return;
    grid.innerHTML = pics.length ? pics.map(x=>`<div class="pic-card" data-id="${x.e.id}">${_hold(`<img src="${enc(x.img)}" loading="lazy" onerror="this.closest('.pic-card')&&this.closest('.pic-card').remove()">`, x.img)}</div>`).join('') : '<div class="empty">No pics found yet.</div>';
    $$('.pic-card',grid).forEach(c=> c.onclick=()=> openThread(c.dataset.id));
  }

  // ---------- 4chan browser (Discover) ----------
  // Board picker + mobile-friendly grid; thumbnails open in the shared lightbox. ----
  const _4CHAN_BOARDS = [['g','/g/ Tech'],['a','/a/ Anime'],['pol','/pol/ Politics'],['h','/h/ NSFW']];
  let _4chanBoard = '4chan' in (window._pcState||{}) ? window._pcState['4chan'] : 'g';

  async function render4chan(){
    const feed=$('#feed');
    feed.innerHTML = `<div class="fc-bar">${_4CHAN_BOARDS.map(([b,l])=>
      `<button class="fc-tab${b===_4chanBoard?' on':''}${b==='h'?' nsfw':''}" data-board="${b}">${enc(l)}</button>`).join('')}</div>
      <div class="fc-grid" id="fc-grid"><div class="spinner"></div></div>`;
    $$('.fc-tab',feed).forEach(t=> t.onclick=()=>{ _4chanBoard=t.dataset.board; (window._pcState=window._pcState||{})['4chan']=_4chanBoard; render4chan(); });
    let data=null;
    try{ const r=await fetch('/api/4chan/catalog?board='+encodeURIComponent(_4chanBoard)); if(!r.ok) throw 0; data=await r.json(); }
    catch(_){ const g=$('#fc-grid'); if(g) g.innerHTML='<div class="empty">Couldn\'t load /'+enc(_4chanBoard)+'/ — the board may be blocked or 4chan is unreachable.</div>'; return; }
    if(VIEW!=='4chan') return;
    const grid=$('#fc-grid'); if(!grid) return;
    const threads=(data&&data.threads)||[];
    grid.innerHTML = threads.length ? threads.map(t=>
      `<div class="fc-card" data-id="${enc(String(t.thread_id))}">
        ${t.thumb_url?`<img class="fc-thumb" src="${enc('/api/4chan/proxy?url='+encodeURIComponent(t.thumb_url))}" loading="lazy" onerror="this.style.visibility='hidden'">`:'<div class="fc-thumb"></div>'}
        <div class="fc-card-body"><div class="fc-title">${enc(t.title||'(no subject)')}</div>
          <div class="fc-meta">💬 ${t.replies||0} · 🖼 ${t.images||0}</div></div>
      </div>`).join('') : '<div class="empty">No threads.</div>';
    $$('.fc-card',grid).forEach(c=> c.onclick=()=> open4chanThread(_4chanBoard, c.dataset.id));
  }

  async function open4chanThread(board, id){
    const feed=$('#feed');
    feed.innerHTML = `<div class="fc-thread-top">
        <button class="btn btn-ghost small" id="fc-back"><svg class="ic b-ic" aria-hidden="true"><use href="#i-arrow-left"></use></svg>/${enc(board)}/</button>
        <a class="btn btn-ghost small" href="https://boards.4chan.org/${enc(board)}/thread/${enc(id)}" target="_blank" rel="noopener">Open on 4chan ↗</a>
        <button class="btn btn-cyan small" id="fc-sum"><svg class="ic b-ic" aria-hidden="true"><use href="#i-ai"></use></svg>Summarize</button>
        <button class="btn btn-neon small" id="fc-share"><svg class="ic b-ic" aria-hidden="true"><use href="#i-send"></use></svg>Share</button>
      </div>
      <div class="fc-summary hidden" id="fc-summary"></div>
      <div class="fc-posts" id="fc-posts"><div class="spinner"></div></div>`;
    $('#fc-back').onclick=()=> render4chan();
    $('#fc-sum').onclick=()=> summarize4chan(board, id);
    // Share on Nostr → open the composer pre-filled with the thread link
    $('#fc-share').onclick=()=> compose({text: `https://boards.4chan.org/${board}/thread/${id}`});
    let data=null;
    try{ const r=await fetch(`/api/4chan/thread?board=${encodeURIComponent(board)}&thread_id=${encodeURIComponent(id)}`); if(!r.ok) throw 0; data=await r.json(); }
    catch(_){ const p=$('#fc-posts'); if(p) p.innerHTML='<div class="empty">Couldn\'t load the thread.</div>'; return; }
    if(VIEW!=='4chan') return;
    const posts=(data&&data.posts)||[]; const box=$('#fc-posts'); if(!box) return;
    box.innerHTML = posts.length ? posts.map(p=>{
      // The thread endpoint ALREADY returns thumb_url/image_url as /api/4chan/proxy paths — use them
      // as-is (re-wrapping them double-proxied → broken → no image). Show the small THUMBNAIL to save
      // bandwidth; tap opens the full-size image (or video) in the lightbox.
      let media='';
      if(p.thumb_url){
        const isVid=/\.(webm|mp4|m4v|mov|ogg)$/i.test(p.image_url_direct||p.image_url||'');
        // tabindex + role: this is an <a> with no href, so Tab skipped it and the images in a thread could
        // not be opened from the keyboard at all. Enter/Space are wired below.
        media=`<a class="fc-post-thumb${isVid?' vid':''}" tabindex="0" role="button" aria-label="Open ${isVid?'video':'image'}" data-full="${enc(p.image_url||p.thumb_url)}" data-kind="${isVid?'video':'image'}">`
            + `<img src="${enc(p.thumb_url)}" loading="lazy" onerror="this.parentNode.style.display='none'">`
            + `${isVid?'<span class="fc-play">▶</span>':''}</a>`;
      }
      const body = p.com ? `<div class="fc-post-body">${enc(p.com)}</div>` : '';
      return `<div class="fc-post"><div class="fc-post-hd"><span class="fc-no">#${enc(String(p.no))}</span> <span class="fc-name">${enc(p.name||'Anonymous')}</span></div>${media}${body}</div>`;
    }).join('') : '<div class="empty">No posts.</div>';
    $$('.fc-post-thumb',box).forEach(a=>{
      a.onclick=()=> openLightbox(a.dataset.full, a.dataset.kind==='video'?'video':undefined);
      a.onkeydown=e=>{ if(e.key==='Enter'||e.key===' '||e.key==='Spacebar'){ e.preventDefault(); a.click(); } };
    });
  }

  async function summarize4chan(board, id){
    const box=$('#fc-summary'); if(!box) return;
    box.classList.remove('hidden'); box.innerHTML='<div class="spinner"></div>';
    try{
      const r=await fetch(`/api/4chan/summarize?board=${encodeURIComponent(board)}&thread_id=${encodeURIComponent(id)}`, {credentials:'include'});
      const j=await r.json().catch(()=>({}));
      box.innerHTML = (r.ok && j.summary) ? `<h4><svg class="ic h-ic" aria-hidden="true"><use href="#i-ai"></use></svg>Summary</h4>${linkify(j.summary)}` : `<div class="muted">${enc(j.error||'Summary unavailable (needs AI access).')}</div>`;
    }catch(_){ box.innerHTML='<div class="muted">Summary failed.</div>'; }
  }

  // Files view = two tabs: Public (your built-in Blossom blobs, shareable URLs) and AI Chat
  // (encrypted artifacts under your storage key, only readable here). The active tab is remembered
  // so re-rendering after an upload/delete stays put.
  let _filesTab = 'public';
  let _filesAdminPk = null;   // when set, the Admin tab is drilled into this user's files
  function openMusicFolder(){ _filesTab='public'; _filesFolder='Music'; switchView('blossom'); }   // the file-manager Music folder
  function openMusic(){   // the Music nav button → shuffle-play your whole library right away
    FilesIdx.loadLocal();
    const go=()=>{ const tracks=musicTracks(null);
      if(!tracks.length){   // no music yet → open the Music folder + guide them
        openMusicFolder();
        modal(`<h3><svg class="ic h-ic" aria-hidden="true"><use href="#i-music"></use></svg>Your music library is empty</h3>
          <p class="muted small">Add some songs to start playing:</p>
          <div class="muted small" style="line-height:1.9;margin:10px 0">
            1. You're now in <b>Files → 🎵 Music</b><br>
            2. <b>Drag &amp; drop audio files</b> into the drop zone (or tap “choose files”)<br>
            3. Each track is <b>Opus-compressed + encrypted</b> automatically<br>
            4. Then the <b>🎵 Music</b> button shuffle-plays your whole library
          </div>
          <div class="row" style="justify-content:flex-end"><button class="btn btn-cyan" id="nm-ok">Got it</button></div>`,
          root=>{ const b=$('#nm-ok',root); if(b) b.onclick=closeModal; });
        return;
      }
      MusicPlayer.shuffle=true; MusicPlayer.refreshQueue();
      MusicPlayer.play(MusicPlayer.queue[Math.floor(Math.random()*MusicPlayer.queue.length)]); };
    // Reconcile against the server before playing, so deleted songs can't be queued (and an emptied
    // library correctly shows the "add some music" guide instead of failing track by track).
    const ready = FilesIdx._pulled ? Promise.resolve() : (FilesIdx._pulled=true, FilesIdx.pull());
    Promise.resolve(ready).then(_refreshBlobHave).then(go, go);
  }
  async function renderBlossom(){
    const feed=$('#feed');
    feed.innerHTML=`<div class="files-tabs">
        <button class="ftab${_filesTab==='public'?' active':''}" data-ft="public">🌸 Public</button>
        <button class="ftab${_filesTab==='ai'?' active':''}" data-ft="ai"><svg class="ic b-ic" aria-hidden="true"><use href="#i-ai"></use></svg>AI Chat</button>
        ${IS_ADMIN?`<button class="ftab${_filesTab==='admin'?' active':''}" data-ft="admin"><svg class="ic b-ic" aria-hidden="true"><use href="#i-shield"></use></svg>Admin</button>`:''}
      </div><div id="files-pane"></div>`;
    $$('.ftab',feed).forEach(b=> b.onclick=()=>{ _filesAdminPk=null; _filesTab=b.dataset.ft; renderBlossom(); });
    const pane=$('#files-pane',feed);
    if(_filesTab==='admin') return renderBlossomAdmin(pane);
    if(_filesTab==='ai') return renderAiFiles(pane);
    return renderPublicFiles(pane);
  }
  // Admin tab: per-user storage overview. Tap a row → review that user's files; tap avatar/name → profile.
  async function renderBlossomAdmin(pane){
    if(!IS_ADMIN){ pane.innerHTML='<div class="empty">Admins only.</div>'; return; }
    if(_filesAdminPk) return renderBlossomAdminUser(pane, _filesAdminPk);
    pane.innerHTML='<div class="spinner"></div>';
    let users=[], total=0, err='';
    try{
      const auth=await sign(27235,'blossom-usage',[['p',ME.pubkey]]);   // content 'blossom-usage' binds the admin proof to THIS action (server checks it)
      const r=await fetch('/client/admin-blossom-usage',{method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify({auth:btoa(JSON.stringify(auth))})}).then(r=>r.json());
      if(r&&r.ok){ users=r.users||[]; total=r.total||0; } else err=(r&&r.error)||'failed';
    }catch(_){ err='request failed'; }
    if(err){ pane.innerHTML='<div class="empty">'+enc(err)+'</div>'; return; }
    if(!users.length){ pane.innerHTML='<div class="empty">No Blossom uploads on this server yet.</div>'; return; }
    const miss=users.map(u=>u.pubkey).filter(pk=>!Store.haveProfile(pk)).slice(0,300);
    if(miss.length){ try{ (await Relay.query([{authors:miss,kinds:[0],limit:miss.length}])).forEach(e=>Store.saveProfile(e)); }catch(_){} }
    pane.innerHTML=`<div style="display:flex;gap:10px;padding:10px 4px 6px;flex-wrap:wrap">
        <div style="flex:1;min-width:120px;background:var(--panel,#16161c);border:1px solid var(--border,#333);border-radius:12px;padding:10px 14px">
          <div style="font-size:22px;font-weight:700;line-height:1.1;color:var(--cyan,#0ff)">${users.length}</div>
          <div class="muted" style="font-size:12px">📊 uploader${users.length===1?'':'s'}</div>
        </div>
        <div style="flex:1;min-width:120px;background:var(--panel,#16161c);border:1px solid var(--border,#333);border-radius:12px;padding:10px 14px">
          <div style="font-size:22px;font-weight:700;line-height:1.1;color:var(--cyan,#0ff)">${_fmtBytes(total)}</div>
          <div class="muted" style="font-size:12px">💾 total stored</div>
        </div>
      </div>
      <div class="muted small" style="padding:2px 6px 8px">Tap a row to review files · tap an avatar or name for their profile</div>
      <div class="people-list">${users.map((u,i)=>{ const p=Store.profile(u.pubkey)||{}; const nm=p.name||p.display_name||(u.npub.slice(0,12)+'…');
        return `<div class="psearch badm-row" data-i="${i}" style="cursor:pointer">
          <img src="${enc(p.picture||LOGO)}" class="badm-prof" data-pk="${u.pubkey}" style="cursor:pointer" onerror="this.src='${LOGO}'">
          <div class="pinfo"><b class="badm-prof" data-pk="${u.pubkey}" style="cursor:pointer">${enc(nm)}</b><div class="muted small">${enc(u.npub.slice(0,18))}… · ${u.count} file(s)</div></div>
          <span style="align-self:center;text-align:right"><b>${_fmtBytes(u.size)}</b><br><span class="muted small">review ›</span></span>
        </div>`; }).join('')}</div>`;
    $$('.badm-prof',pane).forEach(el=> el.onclick=(e)=>{ e.stopPropagation(); renderProfileView(el.dataset.pk); });
    $$('.badm-row',pane).forEach(el=> el.onclick=()=>{ _filesAdminPk=users[+el.dataset.i].pubkey; renderBlossom(); });
  }
  // Admin drill-in: a moderation grid of ONE user's public blobs from THIS node's built-in Blossom server
  // (CFG.blossom_url — the SAME store the usage overview is computed from, not the admin's own configured
  // mediaServer()). Tiles load DOWNSCALED ?thumb=1 previews and link to the full blob in a new tab; reuses
  // the existing purge for deletion.
  async function renderBlossomAdminUser(pane, pk){
    const server=(CFG.blossom_url||mediaServer()||'').replace(/\/$/,'');
    const p=Store.profile(pk)||{}; const nm=p.name||p.display_name||(NT().nip19.npubEncode(pk).slice(0,14)+'…');
    pane.innerHTML=`<div class="row" style="align-items:center;gap:8px;padding:6px 4px">
        <button class="btn btn-ghost small" id="badm-back">‹ Back</button>
        <img src="${enc(p.picture||LOGO)}" class="badm-prof" data-pk="${pk}" style="width:28px;height:28px;border-radius:50%;cursor:pointer" onerror="this.src='${LOGO}'">
        <b class="badm-prof" data-pk="${pk}" style="cursor:pointer">${enc(nm)}</b>
        <span style="flex:1"></span>
        <button class="btn small danger" id="badm-purge"><svg class="ic b-ic" aria-hidden="true"><use href="#i-trash"></use></svg>Purge all</button>
      </div><div class="files-grid" id="badm-grid"><div class="spinner"></div></div>`;
    $('#badm-back',pane).onclick=()=>{ _filesAdminPk=null; renderBlossom(); };
    $$('.badm-prof',pane).forEach(el=> el.onclick=()=>renderProfileView(el.dataset.pk));
    // Purge reuses the existing flow; on Cancel it returns without deleting — re-render in place (keep
    // _filesAdminPk) so a cancel doesn't bounce the admin out of the drill-in.
    $('#badm-purge',pane).onclick=async()=>{ await doPurgeBlossom(pk); renderBlossom(); };
    const g=$('#badm-grid',pane);
    if(!server){ g.innerHTML='<div class="empty">Blossom server not configured.</div>'; return; }
    let list=null;
    try{ const r=await fetch(server+'/list/'+pk); if(r.ok) list=await r.json(); }catch(_){}
    if(!list){ g.innerHTML='<div class="empty">Couldn’t load this user’s files.</div>'; return; }
    if(!list.length){ g.innerHTML='<div class="empty">No files.</div>'; return; }
    g.innerHTML = list.map(b=>{
      const full=server+'/'+b.sha256, thumb=full+'?thumb=1', t=(b.type||'').toLowerCase(), sz=_fmtBytes(b.size||0);
      const isImg=t.startsWith('image/'), isVid=t.startsWith('video/');
      let inner;
      if(isImg||isVid) inner=`<img src="${enc(thumb)}" loading="lazy" style="width:100%;height:100%;object-fit:cover" onerror="this.style.display='none'">`+(isVid?`<span style="position:absolute;top:4px;left:4px;font-size:14px;text-shadow:0 0 3px #000">▶</span>`:'');
      else inner=`<div style="display:flex;align-items:center;justify-content:center;height:100%;font-size:24px">📄</div>`;
      return `<a href="${enc(full)}" target="_blank" rel="noopener" title="${enc(t)} · ${sz}" style="position:relative;aspect-ratio:1;display:block;border-radius:8px;overflow:hidden;background:var(--panel,#16161c);border:1px solid var(--border,#333)">${inner}<span style="position:absolute;bottom:0;left:0;right:0;background:rgba(0,0,0,.6);color:#fff;font-size:10px;padding:1px 4px">${sz}</span></a>`;
    }).join('');
  }
  // Folder index — the folder tree + each file's {name,folder,...}. One encrypted doc under the storage
  // key (cross-device, survives PWA reinstalls), cached in localStorage for instant render. Blossom is
  // flat/content-addressed, so foldering is this client-side overlay keyed by blob sha256.
  const FilesIdx = {
    // _pullDone = a pull attempt finished. _pullOk = the pull actually MATERIALISED the index (or
    // proved the server has none). _pullBlocked = the server HAS an index we could not read — the one
    // state in which writing anything would destroy it. The three are not the same thing, and
    // conflating _pullDone with "we have the index" is what wiped a drive's folders: see _save/_gc.
    data: { folders: ['Music'], files: {}, encFolders: [] }, _pulled:false, _pullDone:false, _pullOk:false, _pullBlocked:false, _t:null, mk:null, _mkWrapped:null, _batch:false, _lastIndexSha:null, _indexShas:new Set(), _dirty:false, _saving:false,
    _key(){ return 'pc_files_idx_'+((ME&&ME.pubkey)||'anon'); },
    _norm(){ if(!this.data||typeof this.data!=='object') this.data={folders:['Music'],files:{},encFolders:[]};
      if(!Array.isArray(this.data.folders)) this.data.folders=['Music'];
      if(!this.data.files||typeof this.data.files!=='object') this.data.files={};
      if(!Array.isArray(this.data.encFolders)) this.data.encFolders=[];   // names of encrypted folders
      if(!this.data.folders.includes('Music')) this.data.folders.unshift('Music'); return this.data; },
    loadLocal(){ try{ const d=JSON.parse(localStorage.getItem(this._key())||'null'); if(d) this.data=d; }catch(_){}
      try{ this._mkWrapped = localStorage.getItem(this._key()+'_mk') || this._mkWrapped; }catch(_){} return this._norm(); },
    saveLocal(){ this._norm(); try{ localStorage.setItem(this._key(), JSON.stringify(this.data)); if(this._mkWrapped) localStorage.setItem(this._key()+'_mk', this._mkWrapped); }catch(_){} },
    // The master key (AES-256) is generated once, NIP-44 self-wrapped, and kept in the index pointer.
    async _ensureMK(){
      if(this.mk) return this.mk;
      // A wrapped key that won't unwrap (signer not ready / wrong account / NIP-44 denied) must FAIL,
      // never silently mint a replacement: the new key can't read the existing encrypted index or Music
      // blobs, and re-wrapping it over the old one in localStorage destroys the only way back to them.
      if(this._mkWrapped){ this.mk=_b64u8(JSON.parse(await signer.nip44dec(ME.pubkey,this._mkWrapped)).k); return this.mk; }
      this.mk=crypto.getRandomValues(new Uint8Array(32));
      this._mkWrapped=await signer.nip44enc(ME.pubkey, JSON.stringify({k:_u8b64(this.mk)})); this.saveLocal();
      return this.mk;
    },
    /* Fold a server index UNDER the local one: folders/encFolders union, per-file local wins (a local
       entry is the newer edit). Used only when a pull lands while edits are pending — the alternative
       there is dropping one side, and dropping the server's side loses the whole drive's foldering.
       The known cost is that a folder deleted locally in that window can come back; resurrecting a
       folder is recoverable, replacing 400 files' metadata with nothing is not. */
    _merge(srv){
      this._norm();
      const loc=this.data;
      this.data={ folders:[...new Set([...(srv.folders||[]), ...loc.folders])],
                  encFolders:[...new Set([...(srv.encFolders||[]), ...loc.encFolders])],
                  files:Object.assign({}, srv.files||{}, loc.files||{}) };
      this.saveLocal();
    },
    async pull(){
      try{ const auth=await sign(27235,'files-index',[['p',ME.pubkey]]);
        const r=await fetch('/client/files-index',{method:'POST',headers:{'Content-Type':'application/json'},
          body:JSON.stringify({pubkey:ME.pubkey,auth:btoa(JSON.stringify(auth))})}).then(r=>r.json());
        const ptr=r&&r.ok&&r.index;
        if(ptr&&typeof ptr==='object'){
          if(ptr.mk) this._mkWrapped=ptr.mk;
          let idx=null;
          if(ptr.indexSha){                         // v2: index lives in an encrypted Blossom blob (scales to 1000s)
            this._lastIndexSha=ptr.indexSha;        // remembered so the grid can hide the index blob itself
            this._indexShas.add(ptr.indexSha);
            // Own try: a signer that can't unwrap the master key, an offline media host or a 404'd blob
            // must fall through to the _pullBlocked check below, NOT escape to the outer catch — which
            // would leave us looking like a fresh empty drive that is safe to overwrite.
            try{
              await this._ensureMK();               // (without this, every session leaked its old index blob)
              const br=await fetch(mediaServer()+'/'+ptr.indexSha);
              if(br.ok){ const d=JSON.parse(new TextDecoder().decode(await _masterDecrypt(this.mk, new Uint8Array(await br.arrayBuffer()))));
                if(d&&d.files) idx=d; }
            }catch(e){ console.warn('files-index: could not read index blob', e); }
          } else if(ptr.files){ idx=ptr; }          // v1: small index stored inline in the pointer
          // Don't clobber edits made WHILE this (possibly slow blob-fetch) pull was in flight — local is
          // newer and syncs on the next save. Without this, creating a folder + uploading during the
          // initial load got wiped: the files lost their metadata and vanished / showed as octet-stream.
          if(idx){
            if(!this._dirty && !this._saving){
              // SELF-REPAIR. If this device holds far more than the server does, the server's copy was
              // truncated (a browser with no local state saved its empty default over it — the wipe
              // this whole guard-set exists to stop). Blindly applying the server copy here is what
              // would finish the job: the last good index would be overwritten by the bad one and the
              // drive's folders would be gone for good. Keep ours, fold theirs under it, push it back.
              const locN=Object.keys(this._norm().files||{}).length, srvN=Object.keys(idx.files||{}).length;
              if(locN >= 5 && locN > srvN + 4){
                this._merge(idx);
                this._dirty=true;
                try{ toast(`📁 Restored ${Object.keys(this.data.files).length} files and ${this.data.folders.length} folders from this device.`); }catch(_){}
                console.warn('files-index: server copy was truncated ('+srvN+' vs '+locN+' here) — restoring from this device');
                setTimeout(()=>this._save(), 50);   // _pullOk is set a few lines below, in this same tick
              } else { this.data=idx; this.saveLocal(); }
            }
            // Edits in flight: the old code SKIPPED the server index entirely, so a first upload on a
            // fresh device saved {Music, that one file} straight over a full drive. Fold the server's
            // index UNDER the local edits instead — local wins per file, nothing is dropped.
            else this._merge(idx);
          }
          // Did we actually GET the index? A pointer that names a blob we couldn't fetch or decrypt is
          // the dangerous case: the server HAS folders, we're holding an empty default, and the next
          // save would replace theirs with ours. Flag it and refuse to write until a pull succeeds.
          if(idx) this._pullOk=true;
          else if(ptr.indexSha || (ptr.files && Object.keys(ptr.files).length)) this._pullBlocked=true;
          else this._pullOk=true;                 // a pointer with nothing in it: server really is empty
        } else if(r && r.ok){
          this._pullOk=true;                      // server has no index at all — a fresh drive, safe to save
        }
        this._pullDone=true;
      }catch(_){}
      return this._norm();
    },
    push(){ this._dirty=true; this.saveLocal(); if(this._batch) return; clearTimeout(this._t); this._t=setTimeout(()=>this._save(), 900); },
    async _save(){
      // NEVER overwrite a server index we failed to READ. The doc is replaceable, so one save from a
      // browser holding the empty default (fresh device, cleared storage, a blob fetch that 404'd)
      // replaces every folder and filename with nothing — which is exactly how a drive lost its
      // folders while all 417 blobs sat untouched in Blossom. Retry the pull once; if it still can't
      // be read, keep the edit local (_dirty stays set) and say so rather than writing over it.
      // The gate is "we have CONFIRMED what's on the server" (_pullOk), not "the pull didn't set an
      // error flag" — an errored/unauthorised pull sets neither, and defaulting that to "safe to
      // write" is the same mistake one level along.
      if(!this._pullOk){
        await this.pull();
        if(!this._pullOk){
          console.warn('files-index: server index unreadable — not saving (would overwrite it)');
          try{ toast('⚠️ Couldn\'t read your folders from the server — not saving, so your existing folders aren\'t overwritten. Try reloading.'); }catch(_){}
          return;
        }
      }
      this._saving=true;   // while a save's index-blob upload + POST is in flight the server is NOT yet
                           // up to date — pull() must not apply stale server data during this window (it
                           // would wipe the very file being saved). Cleared in finally.
      try{ this._norm();
        this._dirty=false;   // capture point: edits AFTER this re-mark dirty (and reschedule) so pull won't clobber them
        const idx={folders:this.data.folders, files:this.data.files, encFolders:this.data.encFolders}; const json=JSON.stringify(idx);
        // `n` is the entry count in PLAINTEXT. The index body may be an encrypted blob the server
        // cannot read, so without this it has no way to notice a save collapsing 400 files to 1 —
        // which is the write it must refuse. Cheap, leaks only a magnitude.
        const ptr={n:Object.keys(idx.files||{}).length}; if(this._mkWrapped) ptr.mk=this._mkWrapped;
        if(json.length < 45000){ ptr.folders=idx.folders; ptr.files=idx.files; ptr.encFolders=idx.encFolders; }   // small → inline (NIP-44 doc)
        else {                                                                       // large → encrypted Blossom blob
          const mk=await this._ensureMK(); ptr.mk=this._mkWrapped;
          // MIRRORED (no noMirror): every ordinary photo is DR-copied to a second host, and the one
          // file holding every filename and folder was the sole exception — backwards. It is
          // ciphertext, so the mirror learns nothing, and it is the blob worth having off-site.
          const url=await uploadBlob(new File([await _masterEncrypt(mk, new TextEncoder().encode(json))],'files-index.enc',{type:'application/octet-stream'}));
          ptr.indexSha=_shaFromUrl(url);
        }
        const auth=await sign(27235,'files-index',[['p',ME.pubkey]]);
        const sr=await fetch('/client/files-index',{method:'POST',headers:{'Content-Type':'application/json'},
          body:JSON.stringify({pubkey:ME.pubkey,auth:btoa(JSON.stringify(auth)),index:ptr})});
        // 409 = the server refused a write that would collapse the index. That is right when it's a
        // bug and wrong when the user genuinely just deleted a big folder — and since nothing else
        // ever sets `force`, without this branch the guard makes a legitimate mass-delete impossible.
        // So ASK, and honour the answer. Never report success for a write the server threw away.
        if(sr && sr.status===409){
          let why=''; try{ why=((await sr.json())||{}).error||''; }catch(_){}
          console.warn('files-index: server refused a collapsing save —', why);
          const intended = await uiConfirm('This removes most of your file list ('+(why.replace(/^refused: /,'')||'large drop')+
            ').\n\nIf you just deleted a folder, that\'s expected — continue?\n\nIf you did NOT expect this, cancel: '+
            'your file list is still safe on the server.');
          if(!intended){
            this._dirty=true;
            try{ toast('Kept your file list — nothing was changed on the server.'); }catch(_){}
            return;
          }
          const auth2=await sign(27235,'files-index',[['p',ME.pubkey]]);
          const fr=await fetch('/client/files-index',{method:'POST',headers:{'Content-Type':'application/json'},
            body:JSON.stringify({pubkey:ME.pubkey,auth:btoa(JSON.stringify(auth2)),index:ptr,force:true})});
          if(!fr || !fr.ok){ this._dirty=true; throw new Error('files-index forced save HTTP '+(fr?fr.status:'?')); }
        } else if(!sr || !sr.ok) throw new Error('files-index save HTTP '+(sr?sr.status:'?'));
        // The superseded index blob is deliberately KEPT. It is ~133 KB and it is the only
        // standalone backup of every filename and folder on the drive — deleting it to reclaim
        // that space is what left a wiped index with nothing to restore from.
        if(ptr.indexSha){ this._lastIndexSha=ptr.indexSha; this._indexShas.add(ptr.indexSha); }
      }catch(e){
        // The edit is NOT saved, so it must not stay marked clean: `_dirty=false` was set at the
        // capture point above, and leaving it there tells the next pull() it's free to overwrite local
        // with the server's copy — silently discarding the rename/move/upload that just failed.
        this._dirty=true;
        console.warn('files-index save failed', e);
      }
      finally{ this._saving=false; }
    },
    beginBatch(){ this._batch=true; },
    async endBatch(){ this._batch=false; await this._save(); },
    folders(){ return this._norm().folders; },
    isEncFolder(name){ return name==='Music' || this._norm().encFolders.includes(name); },   // Music is always encrypted
    addFolder(name, enc){ name=(name||'').trim().slice(0,40); if(!name||this._norm().folders.includes(name)) return false; this.data.folders.push(name); if(enc&&!this.data.encFolders.includes(name)) this.data.encFolders.push(name); this.push(); return true; },
    removeFolder(name){ this._norm(); if(name==='Music'||!name) return false; this.data.folders=this.data.folders.filter(f=>f!==name); this.data.encFolders=this.data.encFolders.filter(f=>f!==name); for(const sha in this.data.files){ if(this.data.files[sha].folder===name) this.data.files[sha].folder=''; } this.push(); return true; },
    meta(sha){ return this._norm().files[sha]||null; },
    folderOf(sha){ const m=this._norm().files[sha]; return (m&&m.folder)||''; },
    setFile(sha, m){ this._norm(); this.data.files[sha]=Object.assign(this.data.files[sha]||{}, m); this.push(); },
    move(sha, folder){ this._norm(); this.data.files[sha]=Object.assign(this.data.files[sha]||{}, {folder}); this.push(); },
    forget(sha){ this._norm(); delete this.data.files[sha]; this.push(); },
  };
  function _shaFromUrl(url){ const m=String(url||'').match(/([0-9a-f]{64})/i); return m?m[1].toLowerCase():''; }
  let _filesFolder = '';   // current folder ('' = All)
  // Pagination for the FILES GRID only (NOT the Music list — the player needs the whole queue). Render
  // a page at a time so a big folder doesn't fire hundreds of thumbnail requests (CPU) at once.
  const _FILES_PAGE = 60;
  let _filesShown = _FILES_PAGE, _filesShownFolder = null;
  // Public tab — your Blossom blobs, organised into client-side folders. Drag-drop + folders + grid.
  async function renderPublicFiles(pane){
    const server=mediaServer();
    if(!server){ pane.innerHTML='<div class="empty">Blossom server not configured.</div>'; return; }
    FilesIdx.loadLocal();
    if(!FilesIdx._pulled){ FilesIdx._pulled=true; FilesIdx.pull().then(()=>{ if(VIEW==='blossom') renderBlossom(); }); }
    pane.innerHTML='<div class="spinner"></div>';
    // Anything that throws below leaves this spinner on screen forever unless it is caught, and
    // "a spinner that never stops" tells the user nothing and tells us less. Surface it instead.
    let canUp=false;
    try{ canUp=await blossomCanUpload(); }
    catch(e){ console.warn('blossom: upload probe failed', e); canUp=true; }   // inconclusive → let the real PUT decide
    const folders=FilesIdx.folders();
    const folderBar = `<div class="folder-bar">
        <button class="folder-chip${_filesFolder===''?' active':''}" data-folder=""><svg class="ic b-ic" aria-hidden="true"><use href="#i-folder"></use></svg>All</button>
        ${folders.map(f=>`<button class="folder-chip${_filesFolder===f?' active':''}" data-folder="${enc(f)}">${f==='Music'?'🎵':(FilesIdx.isEncFolder(f)?'🔒':'📁')} ${enc(f)}</button>`).join('')}
        <button class="folder-chip newfolder" id="bl-newfolder"><svg class="ic b-ic" aria-hidden="true"><use href="#i-plus"></use></svg>New folder</button>
        ${(_filesFolder && _filesFolder!=='Music') ? `<button class="folder-chip delfolder" id="bl-delfolder" title="Delete this folder"><svg class="ic b-ic" aria-hidden="true"><use href="#i-trash"></use></svg>Delete “${enc(_filesFolder)}”</button>` : ''}
      </div>`;
    const head = canUp
      ? `${folderBar}<div class="drop-zone" id="bl-drop"><input type="file" id="bl-file" multiple ${_filesFolder==='Music'?'accept="audio/*"':''} hidden><input type="file" id="bl-folder" webkitdirectory hidden>
          <div class="dz-inner"><span class="dz-ic">⬆</span> Drop files/folders here, or <button class="btn btn-cyan small" id="bl-pick">choose files</button> <button class="btn btn-neon small" id="bl-pickfolder"><svg class="ic b-ic" aria-hidden="true"><use href="#i-folder"></use></svg>choose folder</button>
          <div class="muted small">→ ${_filesFolder?((FilesIdx.isEncFolder(_filesFolder)?'🔒 ':'📁 ')+enc(_filesFolder)):'All files'} · uploaded one at a time${_filesFolder==='Music'?' · non-audio skipped':(FilesIdx.isEncFolder(_filesFolder)?' · encrypted on this device':'')}</div></div>
          <div class="up-queue" id="bl-queue"></div></div>`
      : `${folderBar}<div class="blossom-locked glass"><b>🔒 Upload access needed</b>
           <p class="muted small">You don't have permission to upload files to this server yet. Request access and the admin can grant it from Admin → Users.</p>
           <button class="btn btn-cyan" id="bl-request">🌸 Request upload access</button></div>`;
    pane.innerHTML = head + '<div class="files-selbar" id="bl-selbar"></div><div class="files-grid" id="bl-grid"><div class="spinner"></div></div>';
    $$('.folder-chip[data-folder]',pane).forEach(b=> b.onclick=()=>{ _filesFolder=b.dataset.folder; renderBlossom(); });
    { const nf=$('#bl-newfolder',pane); if(nf) nf.onclick=_newFolderModal; }
    { const df=$('#bl-delfolder',pane); if(df) df.onclick=async()=>{ if(await uiConfirm('Delete folder “'+_filesFolder+'”? Its files move to All — the files themselves aren\'t deleted.')){ FilesIdx.removeFolder(_filesFolder); _filesFolder=''; renderBlossom(); } }; }
    if(canUp){
      const fileInput=$('#bl-file',pane), folderInput=$('#bl-folder',pane), drop=$('#bl-drop',pane);
      $('#bl-pick',pane).onclick=()=>fileInput.click();
      { const fb=$('#bl-pickfolder',pane); if(fb) fb.onclick=()=>folderInput&&folderInput.click(); }
      fileInput.onchange=()=>{ const fs=[...fileInput.files]; fileInput.value=''; uploadFilesSeq(fs); };
      if(folderInput){ try{ folderInput.webkitdirectory=true; folderInput.setAttribute('webkitdirectory',''); folderInput.setAttribute('directory',''); }catch(_){}
        folderInput.onchange=()=>{ const fs=[...folderInput.files]; folderInput.value=''; uploadFilesSeq(fs); }; }
      drop.ondragover=e=>{ if(e.dataTransfer&&[...(e.dataTransfer.types||[])].includes('Files')){ e.preventDefault(); drop.classList.add('over'); } };
      drop.ondragleave=()=>drop.classList.remove('over');
      drop.ondrop=e=>{ e.preventDefault(); drop.classList.remove('over');
        const dt=e.dataTransfer, items=dt&&dt.items, entries=[];
        // capture FileSystem entries SYNCHRONOUSLY (invalid after the event) so dropped FOLDERS recurse
        if(items&&items.length&&items[0].webkitGetAsEntry){ for(let i=0;i<items.length;i++){ const en=items[i].webkitGetAsEntry(); if(en) entries.push(en); } }
        if(entries.length){ _walkEntries(entries).then(fs=>{ if(fs.length) uploadFilesSeq(fs); }); }
        else { const fs=[...((dt&&dt.files)||[])]; if(fs.length) uploadFilesSeq(fs); }
      };
    } else { const rb=$('#bl-request',pane); if(rb) rb.onclick=()=>requestBlossomAccess(rb); }
    let list=null;
    try{ const r=await fetch(server+'/list/'+ME.pubkey, { cache:'no-store' }); if(!r.ok) throw new Error('HTTP '+r.status); list=await r.json(); }
    catch(e){ const g=$('#bl-grid',pane); if(g) g.innerHTML='<div class="empty">Couldn\'t load files from '+enc(server)+' ('+enc(e.message)+').</div>'; }
    if(list!==null){ _blobHave=new Set(list.map(b=>b.sha256));   // reuse this fetch for the music player's existence check
      // Guarded: a throw in the grid renderer used to escape renderPublicFiles and leave the grid
      // spinner spinning with no error anywhere the user could see.
      try{
        if(_filesFolder==='Music') _renderMusicList($('#bl-grid',pane), list); else _renderFilesGrid($('#bl-grid',pane), list);
      }catch(e){
        console.error('blossom: grid render failed', e);
        const g=$('#bl-grid',pane); if(g) g.innerHTML='<div class="empty">Couldn\'t draw your files ('+enc(e.message||'error')+'). Your files are safe — reload to try again.</div>';
      } }
    // Label saved-stream recordings ("Past streams") so they don't show as anonymous video blobs. This is
    // a cosmetic cross-reference of the user's own VOD list — fetch it ONCE (cached), in the BACKGROUND,
    // and re-render the grid when it lands. Never block the drive's first paint on this (a slow/hung
    // /api/streams/vods must not leave the drive blank), and never re-fetch on every folder switch/move.
    if(list!==null && _filesFolder!=='Music'){
      _ensureVodNames().then(changed=>{
        if(!changed || VIEW!=='blossom' || _filesTab!=='public' || _filesFolder==='Music') return;
        // Apply the freshly-fetched labels onto the CURRENT grid IN PLACE — no re-render, so this can't
        // revert an in-window blob add/remove, flash a spinner, or wipe the upload-progress queue.
        const grid=document.getElementById('bl-grid'); if(!grid) return;
        for(const sha in _vodNameMap){
          if((FilesIdx.meta(sha)||{}).name) continue;                      // a user-named file keeps its own name
          const card=grid.querySelector('.file-card[data-sha="'+sha+'"]'); if(!card) continue;
          const span=card.querySelector('.meta > span'); if(span){ span.textContent=_vodNameMap[sha].slice(0,18); span.title=_vodNameMap[sha]; }
          // ...and the download button, or a recording would still save under its hash after the
          // label said "Stream <date>".
          const dl=card.querySelector('.dlbtn');
          if(dl && dl.dataset.name) dl.dataset.name=downloadName({sha256:sha, url:dl.dataset.url}, _vodNameMap[sha], '');
        }
      });
    }
  }
  let _vodNameMap={};          // sha256 -> "Stream <date>" (or a short sha) for the current user's recorded VODs (drive labels)
  let _vodNamesInflight=false; // a fetch is in progress — blocks a concurrent second fetch from a fast re-render
  let _vodNamesAt=0;           // last-fetch time. TTL-cached so we DON'T refetch every folder-switch, but DO pick up a VOD recorded later this session and recover from an early auth-race failure
  async function _ensureVodNames(){
    if(_vodNamesInflight) return false;
    if(_vodNamesAt && (Date.now()-_vodNamesAt < 60000)) return false;   // cached & fresh → nothing new to apply
    _vodNamesInflight=true; _vodNamesAt=Date.now();                     // stamp up-front → at most ONE attempt per 60s (success OR failure) — no refetch storm on a persistently-failing endpoint
    let changed=false;
    try{ const vr=await _streamFetch('/api/streams/vods');
      if(vr && vr.ok){ const vj=await vr.json(); const m={};
        for(const v of (vj.vods||[])){ if(!v.sha256) continue; const t=+v.started_at||0; const d=new Date(t*1000);
          // With a real start time → "Stream <date> <time>"; without one, fall back to a short sha so two
          // timestamp-less recordings don't collapse to an identical bare "Stream" label.
          m[v.sha256]='Stream '+((!t||isNaN(d.getTime())) ? v.sha256.slice(0,6) : (d.toLocaleDateString()+' '+d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}))); }
        _vodNameMap=m; changed=true; } }
    catch(_){}
    _vodNamesInflight=false;
    return changed;            // failure keeps the stamp → next retry after the 60s TTL (bounded), labels just wait
  }
  // ---------- Files: multi-select for mass operations ----------
  // Selection is a Set of sha256 held OUTSIDE the grid, because the grid re-renders constantly
  // (paging, folder switch, VOD labels landing). Cleared on folder change so a hidden selection in
  // another folder can't be deleted by a later "Delete selected".
  let _filesSel = new Set();
  // Blobs this session has deleted. The DELETE succeeded, but if anything between us and the app
  // serves a stale /list/ the file reappears and the delete looks broken. Filtering on the client
  // makes the grid correct immediately and independently of every cache in the path. Entries are
  // dropped once the server stops listing them, so this can never permanently hide a live file.
  let _filesDeleted = new Set();
  let _filesGridList = null;   // last list _renderFilesGrid drew, so the global click handler can refresh the toolbar
  function _filesSelClear(){ _filesSel.clear(); }
  // The visible, selectable shas for the CURRENT folder+page — "Select all" must mean what's on
  // screen, never the whole drive (3000+ blobs, where a mis-tap would be catastrophic).
  function _filesVisibleShas(grid){
    return [...grid.querySelectorAll('.file-card[data-sha]')].map(c=>c.dataset.sha);
  }
  function _filesSelBar(grid, list){
    const bar=grid.parentNode && grid.parentNode.querySelector('#bl-selbar'); if(!bar) return;
    const vis=_filesVisibleShas(grid), n=_filesSel.size;
    grid.classList.toggle('selmode', n>0);   // drives the card cursor (tap = select, not open)
    const allSel = vis.length && vis.every(sha=>_filesSel.has(sha));
    bar.innerHTML = `<button class="btn btn-ghost small" id="bl-selall">${allSel?'☑':'☐'} Select all${vis.length?' ('+vis.length+')':''}</button>`
      + `<button class="btn btn-ghost small" id="bl-selnone"${n?'':' disabled'}>✖ Select none</button>`
      + `<span class="muted small" style="margin:0 4px">${n?(n+' selected'):'none selected'}</span>`
      + `<button class="btn btn-cyan small" id="bl-seldl"${n?'':' disabled'}><svg class="ic b-ic" aria-hidden="true"><use href="#i-download"></use></svg>Download</button>`
      + `<button class="btn btn-cyan small" id="bl-selmove"${n?'':' disabled'}><svg class="ic b-ic" aria-hidden="true"><use href="#i-folder"></use></svg>Move</button>`
      + `<button class="btn btn-neon small" id="bl-seldel"${n?'':' disabled'} style="color:var(--danger)"><svg class="ic b-ic" aria-hidden="true"><use href="#i-trash"></use></svg>Delete</button>`;
    bar.querySelector('#bl-selall').onclick=()=>{ if(allSel) vis.forEach(sha=>_filesSel.delete(sha)); else vis.forEach(sha=>_filesSel.add(sha)); _renderFilesGrid(grid, list); };
    bar.querySelector('#bl-selnone').onclick=()=>{ _filesSelClear(); _renderFilesGrid(grid, list); };
    bar.querySelector('#bl-seldl').onclick=e=>_filesMassDownload(e.currentTarget, grid, list);
    bar.querySelector('#bl-selmove').onclick=e=>_filesMassMove(e.currentTarget, grid, list);
    bar.querySelector('#bl-seldel').onclick=e=>_filesMassDelete(e.currentTarget, grid, list);
  }
  // Delete every selected blob. ONE confirm for the whole batch (not one per file), and it names the
  // count — a per-file prompt for 40 files is worse than no prompt, people click through it.
  // Sequential, not Promise.all: a Blossom server answering 40 parallel signed DELETEs is a great way
  // to get rate-limited half-way and leave the index disagreeing with the server.
  async function _filesMassDelete(btn, grid, list){
    const shas=[..._filesSel]; if(!shas.length) return;
    if(!await uiConfirm('Delete '+shas.length+' file'+(shas.length>1?'s':'')+'? This removes the bytes from the server and cannot be undone.')) return;
    const server=mediaServer(); let ok=0, fail=0;
    btn.disabled=true;
    for(let i=0;i<shas.length;i++){
      const sha=shas[i]; btn.textContent='deleting '+(i+1)+'/'+shas.length+'…';
      try{
        const auth=await sign(24242,'Delete blob',[['t','delete'],['x',sha],['expiration',String(Math.floor(Date.now()/1000)+3600)]]);
        const res=await fetch(server+'/'+sha,{ method:'DELETE', headers:{'Authorization':'Nostr '+btoa(JSON.stringify(auth))} });
        // 404 = already gone server-side, but still drop it from the index (same rule as delBlob).
        if(res.ok || res.status===404){ FilesIdx.forget(sha); _filesDeleted.add(sha); delete _trackUrls[sha]; ok++; }
        else fail++;
      }catch(_){ fail++; }
    }
    _filesSelClear();
    toast(fail? ('deleted '+ok+', '+fail+' failed') : ('deleted '+ok+' file'+(ok>1?'s':'')));
    renderBlossom();
  }
  // Move every selected file into one folder. Index-only (no bytes move), so this is fast and safe.
  function _filesMassMove(btn, grid, list){
    const shas=[..._filesSel]; if(!shas.length) return;
    const opts=[['__all','🗂 All']].concat(FilesIdx.folders().map(f=>[f,(f==='Music'?'🎵 ':'📁 ')+f]));
    openMenuPopover(btn, opts, v=>{
      shas.forEach(sha=>FilesIdx.move(sha, v==='__all'?'':v));
      _filesSelClear(); toast('moved '+shas.length+' file'+(shas.length>1?'s':'')); renderBlossom();
    });
  }
  // Download every selected file, one at a time. Browsers throttle/block a burst of simultaneous
  // downloads, so this paces them and skips ENCRYPTED files (those need the decrypt path, which
  // prompts per file — offering them here would silently save unreadable ciphertext).
  async function _filesMassDownload(btn, grid, list){
    const shas=[..._filesSel]; if(!shas.length) return;
    const byId={}; (list||[]).forEach(b=>byId[b.sha256]=b);
    let n=0, skipped=0;
    btn.disabled=true;
    for(const sha of shas){
      const b=byId[sha]; if(!b){ skipped++; continue; }
      const m=FilesIdx.meta(sha)||{};
      if(m.enc){ skipped++; continue; }                       // ciphertext — use the per-file ⬇ (decrypts)
      const nm=m.name||b.name||_vodNameMap[sha]||'';
      const ext=extOfBlob(b, m.name?m:{name:nm, mime:m.mime});
      n++; btn.textContent='downloading '+n+'/'+shas.length+'…';
      try{ await downloadBlobFile(b.url, downloadName(b, nm, ext)); }catch(_){}
      await new Promise(r=>setTimeout(r, 400));               // pace — a burst gets blocked as a popup storm
    }
    btn.disabled=false; btn.textContent='⬇ Download';
    toast(skipped? ('downloaded '+n+' · skipped '+skipped+' (encrypted — use the per-file ⬇)') : ('downloaded '+n));
  }

  function _renderFilesGrid(grid, list){
    if(!grid) return;
    _filesGridList = list;
    // hide encrypted MUSIC ciphertext from the normal grid (it lives in the Music folder's track list);
    // encrypted files in other folders DO show, as lock cards that decrypt in-browser on open.
    // Forget tombstones the server has already stopped listing — keeps the set from growing and lets
    // a re-uploaded (same-hash) file come back.
    if(_filesDeleted.size){ const live=new Set(list.map(b=>b.sha256)); [..._filesDeleted].forEach(sha=>{ if(!live.has(sha)) _filesDeleted.delete(sha); }); }
    const inFolder = list.filter(b=>{
      if(_filesDeleted.has(b.sha256)) return false;                            // deleted this session (see _filesDeleted)
      // EVERY index blob, not just the newest. Each edit (upload/delete/move/rename) re-encrypts the
      // whole index and uploads it as a NEW blob, and the superseded one is deliberately kept as the
      // only standalone backup of every filename+folder. Hiding only _lastIndexSha meant that after a
      // delete the FRESH index blob was hidden but the one it replaced popped into the grid — an
      // unnamed ~671KB tile appearing exactly where the deleted file had been, which reads as
      // "the file didn't delete". They are all bookkeeping; none of them is a user file.
      if(b.sha256===FilesIdx._lastIndexSha || FilesIdx._indexShas.has(b.sha256)) return false;
      const m=FilesIdx.meta(b.sha256);
      if(!m && /octet-stream/.test(b.type||'')) return false;                  // stale index blobs / unnamed binaries (the "OCTET-STE" noise)
      if(m && m.enc && FilesIdx.folderOf(b.sha256)==='Music') return false;    // music ciphertext → Music list only
      return _filesFolder==='' ? true : FilesIdx.folderOf(b.sha256)===_filesFolder;
    }).sort((a,b)=>(b.uploaded||0)-(a.uploaded||0));   // NEWEST first — else a fresh upload/VOD is buried at the
                                                       // END of a big (3000+) oldest-first Blossom /list, past the 60-per-page window (the "my recording isn't in the drive" bug)
    if(_filesShownFolder!==_filesFolder){ _filesShownFolder=_filesFolder; _filesShown=_FILES_PAGE; _filesSelClear(); }   // reset paging AND selection on folder change (never act on off-screen files)
    const _shown = inFolder.slice(0, _filesShown), _more = inFolder.length - _shown.length;
    grid.innerHTML = inFolder.length ? (_shown.map(b=>{
      // Name: ours (Files index) → the server's stored upload name → a VOD label. The last two are why
      // a file uploaded from another device/client isn't an anonymous "412KB" tile any more.
      const m=FilesIdx.meta(b.sha256)||{}; const nm=m.name||b.name||_vodNameMap[b.sha256]||'';
      const ext=extOfBlob(b, m.name?m:{name:nm, mime:m.mime});
      const dlName=downloadName(b, nm, ext);
      if(m.enc){   // encrypted file — lock card; opening decrypts in-browser (never exposes the ciphertext URL)
        return `<div class="file-card enc${_filesSel.has(b.sha256)?' selected':''}" draggable="true" data-sha="${b.sha256}"><a href="#" class="enc-open" data-sha="${b.sha256}"><div class="file-icon">🔒<span>${enc(ext||'enc')}</span></div></a>
          <input type="checkbox" class="selbox" data-sha="${b.sha256}"${_filesSel.has(b.sha256)?' checked':''} title="Select">
          <button class="del" data-sha="${b.sha256}" aria-label="Delete"><svg class="ic x-ic" aria-hidden="true"><use href="#i-close"></use></svg></button>
          <div class="meta"><span class="fname" title="${enc(nm)}">${nm?enc(fileLabel(nm,ext,b.size)):'encrypted'}</span><span class="fc-acts"><button class="dlbtn dlenc" data-sha="${b.sha256}" data-name="${enc(dlName)}" title="Download (decrypts first)"><svg class="ic b-ic" aria-hidden="true"><use href="#i-download"></use></svg></button><button class="movebtn" data-sha="${b.sha256}" title="Move to folder"><svg class="ic b-ic" aria-hidden="true"><use href="#i-folder"></use></svg></button></span></div></div>`;
      }
      return `<div class="file-card${_filesSel.has(b.sha256)?' selected':''}" draggable="true" data-sha="${b.sha256}"><a href="${enc(b.url)}" data-mime="${enc(b.type||'')}" target="_blank">${blobThumb(b, ext)}</a>
        <input type="checkbox" class="selbox" data-sha="${b.sha256}"${_filesSel.has(b.sha256)?' checked':''} title="Select">
        <button class="copy" data-url="${enc(b.url)}" title="Copy URL">⧉</button><button class="del" data-sha="${b.sha256}" aria-label="Delete"><svg class="ic x-ic" aria-hidden="true"><use href="#i-close"></use></svg></button>
        <div class="meta"><span class="fname" title="${enc(nm||dlName)}">${enc(fileLabel(nm,ext,b.size))}</span><span class="fc-acts"><button class="dlbtn" data-url="${enc(b.url)}" data-name="${enc(dlName)}" title="Download ${enc(dlName)}"><svg class="ic b-ic" aria-hidden="true"><use href="#i-download"></use></svg></button><button class="movebtn" data-sha="${b.sha256}" title="Move to folder"><svg class="ic b-ic" aria-hidden="true"><use href="#i-folder"></use></svg></button></span></div></div>`;
    }).join('') + (_more>0 ? `<button class="btn btn-ghost bl-more" data-id="bl-more" style="grid-column:1/-1;margin:10px auto;display:block">↓ Load ${Math.min(_more,_FILES_PAGE)} more · ${_more} left</button>` : '')) : '<div class="empty">No files'+(_filesFolder?(' in '+enc(_filesFolder)):'')+' yet — drop some above.</div>';
    { const mb=$('.bl-more',grid); if(mb) mb.onclick=()=>{ _filesShown+=_FILES_PAGE; _renderFilesGrid(grid, list); }; }
    $$('.enc-open',grid).forEach(a=> a.onclick=async e=>{ e.preventDefault(); try{ toast('decrypting…'); const u=await trackUrl(a.dataset.sha); window.open(u,'_blank'); }catch(err){ toast('decrypt failed: '+(err.message||'')); } });
    $$('.vthumb',grid).forEach(im=> im.onerror=()=>{ const d=document.createElement('div'); d.className='file-icon'; d.innerHTML='🎬<span>'+enc(im.dataset.ext||'video')+'</span>'; im.replaceWith(d); });
    // Encrypted files can't be downloaded by URL (that would save the ciphertext) — decrypt in the
    // browser first, then save the plaintext under its real name.
    $$('.dlenc',grid).forEach(b=> b.onclick=e=>{ e.preventDefault(); e.stopPropagation(); saveEncrypted(b.dataset.sha, b.dataset.name); });
    $$('.del',grid).forEach(b=> b.onclick=()=>delBlob(b.dataset.sha));
    $$('.copy',grid).forEach(b=> b.onclick=()=>copyUrl(b.dataset.url));
    // :not(.dlenc) — encrypted files have their own handler below (decrypt first, never fetch the URL)
    $$('.dlbtn:not(.dlenc)',grid).forEach(b=> b.onclick=e=>{ e.preventDefault(); e.stopPropagation(); downloadBlobFile(b.dataset.url, b.dataset.name); });
    $$('.movebtn',grid).forEach(b=> b.onclick=(e)=>_moveMenu(e.currentTarget, b.dataset.sha));
    $$('.file-card',grid).forEach(card=> card.ondragstart=e=>{ if(e.dataTransfer) e.dataTransfer.setData('text/sha', card.dataset.sha); });
    // Checkbox toggles selection without opening the file (the card's <a> would otherwise swallow it).
    $$('.selbox',grid).forEach(cb=> cb.onclick=e=>{ e.stopPropagation();
      const sha=cb.dataset.sha; if(cb.checked) _filesSel.add(sha); else _filesSel.delete(sha);
      const card=cb.closest('.file-card'); if(card) card.classList.toggle('selected', cb.checked);
      _filesSelBar(grid, list); });
    _filesSelBar(grid, list);
    $$('.folder-chip[data-folder]').forEach(chip=>{
      chip.ondragover=e=>{ e.preventDefault(); chip.classList.add('drop'); };
      chip.ondragleave=()=>chip.classList.remove('drop');
      chip.ondrop=e=>{ e.preventDefault(); chip.classList.remove('drop'); const sha=e.dataTransfer&&e.dataTransfer.getData('text/sha'); if(sha){ FilesIdx.move(sha, chip.dataset.folder); toast('moved to '+(chip.dataset.folder||'All')); renderBlossom(); } };
    });
    // Re-attach the keyboard cursor. _selEl() re-finds the row by key and re-adds .sel, but only when
    // something asks it to — so after "Load more" redraws the grid the highlight vanished until the next
    // keypress, even though the selection was still live (the next Enter loaded another page just fine).
    try{ _selEl(); }catch(_){ }
  }
  function _moveMenu(anchor, sha){
    const opts=[['__all','🗂 All']].concat(FilesIdx.folders().map(f=>[f,(f==='Music'?'🎵 ':'📁 ')+f]));
    openMenuPopover(anchor, opts, v=>{ FilesIdx.move(sha, v==='__all'?'':v); toast('moved'); renderBlossom(); });
  }
  // Upload a batch ONE AT A TIME (sequential), into the current folder, with a per-file progress queue.
  // In the Music folder, audio files go through the compress→encrypt pipeline; everything else uploads
  // straight to Blossom.
  // Recurse dropped folders → a flat File[] (FileSystem entries captured synchronously from the drop).
  async function _walkEntries(entries){
    const out=[];
    async function walk(entry){
      if(entry.isFile){ await new Promise(res=>entry.file(f=>{ out.push(f); res(); }, ()=>res())); }
      else if(entry.isDirectory){ const reader=entry.createReader();
        await new Promise(res=>{ const read=()=>reader.readEntries(async ents=>{ if(!ents.length){ res(); return; } for(const en of ents){ await walk(en); } read(); }, ()=>res()); read(); }); }
    }
    for(const en of entries){ await walk(en); }
    return out;
  }
  // Persistent floating upload progress (appended to <html> so it survives view changes) + a stop button.
  // Generic drag (mouse + touch) for a fixed-position widget; `noDrag` = selector to ignore (buttons etc.)
  function _makeDraggable(el, handle, noDrag){
    if(!el||!handle) return; let sx,sy,ox,oy,on=false;
    const move=e=>{ if(!on) return; const p=e.touches?e.touches[0]:e; el.style.right='auto'; el.style.bottom='auto'; el.style.left=Math.max(0,Math.min(innerWidth-50,ox+p.clientX-sx))+'px'; el.style.top=Math.max(0,Math.min(innerHeight-40,oy+p.clientY-sy))+'px'; if(e.cancelable)e.preventDefault(); };
    const up=()=>{ on=false; removeEventListener('mousemove',move); removeEventListener('mouseup',up); removeEventListener('touchmove',move); removeEventListener('touchend',up); };
    const down=e=>{ if(e.target.closest('button'+(noDrag?(','+noDrag):''))) return; const p=e.touches?e.touches[0]:e; const r=el.getBoundingClientRect(); on=true; sx=p.clientX; sy=p.clientY; ox=r.left; oy=r.top; el.style.right='auto'; el.style.bottom='auto'; el.style.left=ox+'px'; el.style.top=oy+'px'; addEventListener('mousemove',move); addEventListener('mouseup',up); addEventListener('touchmove',move,{passive:false}); addEventListener('touchend',up); };
    handle.onmousedown=down; handle.ontouchstart=down;
  }
  let _uploadCancel=false, _uploadBadgeT=0;
  function _uploadBadge(text, done){
    clearTimeout(_uploadBadgeT);   // a new update cancels a pending auto-remove (so it won't wipe a fresh upload)
    let b=document.getElementById('upload-badge');
    if(text===null){ if(b) b.remove(); return; }
    if(!b){ b=document.createElement('div'); b.id='upload-badge'; document.documentElement.appendChild(b); _makeDraggable(b, b, '.upbadge-x'); }
    b.className='upbadge'+(done?' done':'');
    b.innerHTML=`<span class="upbadge-ic">${done?'✅':'⬆'}</span><span class="upbadge-txt">${enc(text)}</span><span class="upbadge-x" title="${done?'dismiss':'stop'}">✕</span>`;
    const x=b.querySelector('.upbadge-x'); if(x) x.onclick=()=>{ if(done){ _uploadBadge(null); } else { _uploadCancel=true; const t=b.querySelector('.upbadge-txt'); if(t) t.textContent='stopping…'; } };
    if(done) _uploadBadgeT=setTimeout(()=>_uploadBadge(null), 12000);
  }
  // New-folder dialog: name + Encrypted/Public. An encrypted folder AES-encrypts everything dropped in
  // it (client-side, under your master key) before upload — Blossom only ever sees ciphertext.
  function _newFolderModal(){
    modal(`<h3><svg class="ic h-ic" aria-hidden="true"><use href="#i-folder"></use></svg>New folder</h3>
      <label class="fld">Name<input class="input" id="nf-name" placeholder="Folder name" maxlength="40"></label>
      <div class="fld">Contents
        <label class="nf-opt"><input type="radio" name="nf-enc" value="0" checked> 🌐 <b>Public</b><span class="muted small"> — files upload as-is, shareable by URL</span></label>
        <label class="nf-opt"><input type="radio" name="nf-enc" value="1"> 🔒 <b>Encrypted</b><span class="muted small"> — encrypted on this device; only you can open them</span></label>
      </div>
      <div class="row" style="justify-content:flex-end;gap:8px;margin-top:14px"><button class="btn btn-ghost small" id="nf-cancel">Cancel</button><button class="btn btn-neon small" id="nf-create">Create</button></div>`,
      root=>{
        const nm=$('#nf-name',root); if(nm) nm.focus();
        const c=$('#nf-cancel',root); if(c) c.onclick=closeModal;
        const go=()=>{ const name=((nm&&nm.value)||'').trim().slice(0,40); if(!name){ toast('enter a name'); return; }
          const isEnc=(($('input[name="nf-enc"]:checked',root)||{}).value==='1');
          if(FilesIdx.addFolder(name, isEnc)){ _filesFolder=name; closeModal(); renderBlossom(); } else toast('folder exists'); };
        const g=$('#nf-create',root); if(g) g.onclick=go;
        if(nm) nm.addEventListener('keydown',e=>{ if(e.key==='Enter') go(); });
      });
  }
  // Encrypt ANY file with the master key (IV from content → identical input dedups), upload the
  // ciphertext (noMirror), and record it like a music track so trackUrl() can decrypt it on open.
  async function uploadEncFile(file, folder, statEl){
    if(!signer.nip44enc) throw new Error("signer can't encrypt (needs NIP-44)");
    const setS=t=>{ if(statEl) statEl.textContent=t; };
    const mk=await FilesIdx._ensureMK();
    const buf=new Uint8Array(await file.arrayBuffer());
    setS('encrypting…');
    const blob=await _masterEncrypt(mk, buf, await _contentIV(buf));
    setS('uploading…');
    const url=await uploadBlob(new File([blob],(file.name||'file')+'.enc',{type:'application/octet-stream'}), {noMirror:true});
    const sha=_shaFromUrl(url); if(!sha) throw new Error('upload returned no hash');
    FilesIdx.setFile(sha,{name:file.name||'file', folder, mime:file.type||'application/octet-stream', enc:true, mk:true, size:buf.length, ts:Math.floor(Date.now()/1000)});
  }
  async function uploadFilesSeq(files){
    files=files.filter(Boolean); if(!files.length) return;
    const folder=_filesFolder, music=folder==='Music';   // capture: navigating mid-upload won't misfile
    // A FOLDER upload (webkitdirectory / dropped dir) carries webkitRelativePath like "Top/sub/pic.jpg".
    // Preserve that structure instead of flattening everything into one folder: each file lands in a
    // folder derived from its subpath. Capture the paths NOW — compressImage() below returns a fresh File
    // that has NO webkitRelativePath, and the batch may reorder-replace `files`, so read them up front and
    // index-align. _subFolder drops the selected top-level dir (a flat folder still lands in the current
    // folder) and nests any real subfolders under wherever you are. Only the plain path uses it; Music /
    // encrypted folders keep their single-folder behavior.
    const _relPaths=files.map(f=>(f&&f.webkitRelativePath)||'');
    const _subFolder=(i)=>{
      const rel=_relPaths[i]||''; if(!rel.includes('/')) return folder;
      const parts=rel.split('/'); parts.shift();          // drop the selected top folder name
      const dir=parts.slice(0,-1).join('/');              // subdir path (minus the filename)
      if(!dir) return folder;                             // file was directly in the top folder
      return folder ? (folder+'/'+dir) : dir;             // nest the uploaded subfolders under the current one
    };
    // FAIL-CLOSED: never upload into a NAMED folder before the index has loaded. If the folder's
    // encrypted flag isn't known yet, uploading would silently take the PLAINTEXT path and put a
    // world-readable blob on Blossom (the leaked-file bug). Refuse until we know the folder's status.
    if(!music && folder && !FilesIdx._pullDone){ toast('One sec — still loading your folders. Try that again in a moment.'); return; }
    _uploadCancel=false;
    const encFolder=!music && FilesIdx.isEncFolder(folder);   // non-Music encrypted folder → encrypt every file
    const big=files.length>20;   // a folder import → compact summary, not 2000 DOM rows
    const q=$('#bl-queue');
    if(q) q.innerHTML = big ? `<div class="up-summary" id="up-sum">Preparing ${files.length} files…</div>`
      : files.map((f,i)=>`<div class="up-item"><span class="up-name">${enc(f.name)}</span><span class="up-stat" id="up-stat-${i}">queued</span></div>`).join('');
    FilesIdx.beginBatch();   // collapse the index save (a 2000-file import must NOT re-save the index per file)
    // Pre-sign the whole batch: ONE signer prompt instead of one per file (see _signUploadBatch). Encrypted
    // folders are skipped — their bytes are produced per file during the upload, so their hashes aren't
    // knowable up front. Best-effort: on any failure we simply fall back to per-file signing.
    let _batchPrepped=null;
    if(!encFolder && files.length>1){ try{ _batchPrepped=await _signUploadBatch(files); }catch(_){ _batchPrepped=null; } }
    if(_batchPrepped && _batchPrepped.length===files.length) files=_batchPrepped;   // upload the exact bytes we hashed
    // Register the subfolders this upload will populate — setFile only TAGS a file; folders() is a
    // separate registry, so an unregistered folder wouldn't appear in the Files list. Deduped up front
    // (a handful per import, not per file), plain uploads only.
    if(!music && !encFolder){
      const _seen=new Set(FilesIdx.folders());
      for(let i=0;i<files.length;i++){ const tf=_subFolder(i); if(tf && !_seen.has(tf)){ _seen.add(tf); try{ FilesIdx.addFolder(tf); }catch(_){} } }
    }
    let done=0, ok=0, skip=0, fail=0;
    for(let i=0;i<files.length;i++){
      if(_uploadCancel) break;
      const stat=big?null:$('#up-stat-'+i);
      try{
        if(music){
          if(!(files[i].type||'').startsWith('audio/')){ skip++; if(stat) stat.textContent='skipped (not audio)'; }
          else if(_musicHasSrc(files[i])){ skip++; if(stat){ stat.textContent='already imported ✓'; stat.className='up-stat ok'; } }   // resume
          else { await uploadMusicTrack(files[i], stat); ok++; if(stat){ stat.textContent='✓'; stat.className='up-stat ok'; }
            if(++done%25===0){ await FilesIdx.endBatch(); FilesIdx.beginBatch(); } }   // checkpoint so a crash keeps progress
        } else if(encFolder){
          await uploadEncFile(files[i], folder, stat);
          ok++; if(stat){ stat.textContent='🔒'; stat.className='up-stat ok'; }
          if(++done%25===0){ await FilesIdx.endBatch(); FilesIdx.beginBatch(); }
        } else {
          if(stat) stat.textContent='uploading…';
          const url=await uploadBlob(files[i]); const sha=_shaFromUrl(url);
          if(sha) FilesIdx.setFile(sha, {name:files[i].name, folder:_subFolder(i), mime:files[i].type||'', size:files[i].size, ts:Math.floor(Date.now()/1000)});
          ok++; if(stat){ stat.textContent='✓'; stat.className='up-stat ok'; }
          if(++done%25===0){ await FilesIdx.endBatch(); FilesIdx.beginBatch(); }
        }
      }catch(e){ fail++; if(_blossomDenied(e)) requestBlossomAccess(); if(stat){ stat.textContent='✗'; stat.className='up-stat err'; stat.title=e.message||'failed'; } }
      const prog=`${i+1} / ${files.length} · ✓${ok}${skip?' ⏭'+skip:''}${fail?' ✗'+fail:''}`;
      _uploadBadge('Uploading '+prog);   // persists across views
      if(big){ const s=$('#up-sum'); if(s) s.textContent='Uploading… '+prog; }
    }
    await FilesIdx.endBatch();
    _uploadBatchAuth=null;   // the batch auth never outlives its batch (it commits only to THESE hashes)
    const summary=`${_uploadCancel?'Stopped':'Done'} — ✓ ${ok} added${skip?(' · ⏭ '+skip+' skipped'):''}${fail?(' · ✗ '+fail+' failed'):''}`;
    _uploadBadge(summary, true);   // self-removes after 12s (timer lives in _uploadBadge)
    if(big&&q){ const s=$('#up-sum'); if(s) s.textContent=summary; }
    toast(summary);
    setTimeout(()=>{ if(VIEW==='blossom') renderBlossom(); }, 700);
  }

  // ---- Music: Opus-compressed + AES-256-GCM-encrypted tracks in the Music folder ----------------------
  // raw audio → server Opus transcode (compression) → AES-GCM encrypt (random per-file key) → upload the
  // CIPHERTEXT to the user's Blossom → store the NIP-44 self-wrapped key in the index. Playback fetches
  // the ciphertext, unwraps the key, decrypts in-browser → object URL. So Blossom only ever holds opaque
  // ciphertext; only the owner's signer can unwrap it.
  function _u8b64(u8){ let s='',C=0x8000; for(let i=0;i<u8.length;i+=C) s+=String.fromCharCode.apply(null,u8.subarray(i,i+C)); return btoa(s); }
  function _b64u8(b){ const s=atob(b),u=new Uint8Array(s.length); for(let i=0;i<s.length;i++) u[i]=s.charCodeAt(i); return u; }
